INSERT OR IGNORE INTO evidence(id,category_slug,title,url,published_at,kind,evidence_level,review_status,result,limitations,action) VALUES('agent-security-2026','agents/deployment/security','Practical Security Guidance for Sandboxing Agentic Workflows and Managing Execution Risk','https://developer.nvidia.com/blog/practical-security-guidance-for-sandboxing-agentic-workflows-and-managing-execution-risk/','2026-01-30','security_guidance','author_reported','curated','NVIDIA AI red-team guidance identifies indirect prompt injection and recommends OS sandboxing, egress/file restrictions and scoped approvals.','Security guidance, not measured effectiveness of a Bubbles-specific integration.','Keep external evidence as data only; separate read-only research queries from tool execution; restrict credentials and egress.');
INSERT OR IGNORE INTO evidence(id,category_slug,title,url,published_at,kind,evidence_level,review_status,result,limitations,action) VALUES('bench-audit-2026','agents/coding/benchmarks','Separating signal from noise in coding evaluations','https://openai.com/index/separating-signal-from-noise-coding-evaluations/','2026-07-08','benchmark_audit','author_reported','curated','OpenAI audit estimates about 30% of SWE-bench Pro tasks are broken, including overly strict tests and underspecified prompts.','Specific audit methodology and benchmark; result should not be generalized mechanically to all evaluation suites.','Use task-level acceptance oracle, test coverage audit, no-op baseline and direct user-flow verification.');
INSERT OR IGNORE INTO evidence(id,category_slug,title,url,published_at,kind,evidence_level,review_status,result,limitations,action) VALUES('build-to-test-2026','agents/verification/regression','Building to the Test: Coding Agents Deliver What You Check, Not What You Requested','https://www.microsoft.com/en-us/research/publication/building-to-the-test-coding-agents-deliver-what-you-check-not-what-you-requested/','2026-06-01','research_preprint','experimental','curated','In a controlled task with 18 runs and 222 hidden Playwright tests, agents could score near-perfect without shipping the requested reusable library.','One narrow setup; prevalence across models and tasks unknown.','Use artifact-structure checks alongside functional browser tests and user-journey acceptance evidence.');
INSERT OR IGNORE INTO evidence(id,category_slug,title,url,published_at,kind,evidence_level,review_status,result,limitations,action) VALUES('memtrace-2026','agents/context/memory','MemTrace: State-Consistent Memory for Long-Horizon Coding Agents','https://arxiv.org/abs/2610.04838','2026-10-04','research_preprint','author_reported','curated','Authors report +21.2 DeepSWE pass@1 points, +4.4 SWE-EVO resolved-rate points, +17.8 SWE-Milestone points against evaluated baselines.','Preprint; experiment and comparison do not establish performance in QuantaPhi. Claims require independent reproduction.','Use immutable context anchors tied to commit SHA, files and tests; invalidate recalled claims when source revision changes.');
INSERT OR IGNORE INTO evidence(id,category_slug,title,url,published_at,kind,evidence_level,review_status,result,limitations,action) VALUES('probe-2026','agents/recovery/telemetry','PROBE: Failure-Anchored Structured Recovery for Software Engineering Agents','https://www.microsoft.com/en-us/research/publication/debugging-the-debuggers-failure-anchored-structured-recovery-for-software-engineering-agents/','2026-05-01','research_preprint','author_reported','curated','Authors report 65.37% top-1 diagnosis accuracy and 21.79% recovery on 257 initially unresolved cases.','Author-reported controlled evaluation; accurate diagnosis does not guarantee recovery and deployment was not shown for this application.','Capture error, last tool receipt, failing test and environment; require bounded repair guidance plus fresh test/receipt.');
INSERT OR IGNORE INTO evidence(id,category_slug,title,url,published_at,kind,evidence_level,review_status,result,limitations,action) VALUES('repair-trace-2026','agents/recovery/telemetry','Understanding Automated Program Repair Agents Through the Lens of Traceability','https://d3ccyth396mz21.cloudfront.net/publications/understanding-automated-program-repair-agents-through-the-lens-of-traceability-an-empirical-study','2026-10-03','conference_study','independent_study','curated','Study traces five automated program repair agents across 500 repair tasks and identifies failure to reproduce issues, poor regression selection and overfitted fixes.','Findings on selected agents/tasks; not a test of Bubbles or Robot Brain.','Require failing regression reproduction before patch, then independent full-suite and real browser verification.');
INSERT OR IGNORE INTO evidence(id,category_slug,title,url,published_at,kind,evidence_level,review_status,result,limitations,action) VALUES('stratum-2026','agents/context/memory','Stratum: Repository Memory for Coding Agents Beyond the Context Window','https://arxiv.org/abs/2610.36153','2026-10-26','research_preprint','experimental','curated','Authors report 21/24 root-file localization trials versus 6/24 retrieval baseline on eight bugs; a proposed tiered repository memory system.','Small eight-bug experiment; performance/generalization unknown for QuantaPhi, and this is a proposal rather than a production implementation.','Prototype source-scoped history recall with pagination and per-result provenance; test cross-session context validity.');
INSERT OR IGNORE INTO evidence(id,category_slug,title,url,published_at,kind,evidence_level,review_status,result,limitations,action) VALUES('swepro-v2-2026','agents/coding/benchmarks','SWE-Bench Pro V2 updated evaluation protocol','https://labs.scale.com/leaderboard/swe_bench_pro_public_v2','2026-09-22','benchmark_release','author_reported','curated','Publisher reports 642 tasks across 11 repositories; removed 89 invalid tasks; re-grades agent diffs on pristine images.','Public benchmark may still have data leakage or task flaws; score is not direct production confidence.','Use isolated pristine CI recheck and private QuantaPhi task suites; compare changed source against fresh clean workspace.');
